async function renderReports(){reportRows=await api('reports');$('#view').innerHTML=title('EVOLUÇÃO DA ACADEMIA','Acompanhamento de aprendizagem','Progresso, notas e carga horária curricular por aluno e curso.','<a id="exportReport" class="btn secondary" href="/api/lms/reports/export">↓ Exportar CSV</a>')+`<div class="toolbar"><input id="reportSearch" aria-label="Buscar aluno no relatório" placeholder="Nome, RA ou e-mail..."><select id="reportCourse" aria-label="Filtrar curso"><option value="">Todos os cursos</option>${S.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select><select id="reportStatus" aria-label="Filtrar situação"><option value="">Todas as situações</option><option>Não iniciado</option><option>Em andamento</option><option>Concluído</option></select></div><div id="reportSummary" class="stat-grid"></div><div class="table-wrap"><table><thead><tr><th>ALUNO / RA</th><th>CURSO</th><th>PROGRESSO</th><th>NOTA MÉDIA</th><th>HORAS CONCLUÍDAS</th><th>ÚLTIMA ATIVIDADE</th></tr></thead><tbody id="reportBody"></tbody></table></div><p class="small muted">As horas concluídas correspondem à proporção das aulas finalizadas na carga horária cadastrada do módulo. Não representam tempo cronometrado de presença. A nota média considera avaliações corrigidas.</p>`;filterReports()}
