function managementItems(){return [
 ['dashboard','Visão geral','Indicadores e acessos da academia.'],
 ['approvals','Cadastros pendentes',`${S.registrationPendingCount||0} solicitações aguardam análise.`],
 ...(isAdmin()?[['people','Alunos e equipe','Cadastre pessoas, revise perfis e ative ou inative acessos.'],['enrollments','Matrículas','Libere cursos e acompanhe o progresso de cada participante.']]:[]),
 ['reports','Acompanhamento','Progresso, notas, horas e exportação por aluno.'],
 ['moderation','Moderação','Analise denúncias e organize os assuntos da comunidade.'],
 ['courses','Cursos e grades','Organize módulos, aulas, vídeos, portfólios e avaliações.'],
 ['forum','Fórum',isAdmin()?'Acompanhe as conversas e modere as mensagens dos cursos.':'Acompanhe as conversas e responda às dúvidas dos cursos.'],
 ['support','Suporte aos alunos','Responda dúvidas e acompanhe os atendimentos.'],
 ['notifications','Notificações','Publique comunicados para os participantes dos cursos.'],
 ['certificates','Certificados',isAdmin()?'Consulte os certificados emitidos para a academia.':'Consulte seus certificados e o modelo de emissão.'],
 ...(isAdmin()?[['settings','Configurações','Consulte a disponibilidade e configure o tutor com IA.'],['audit','Histórico de ações','Acompanhe os registros das alterações administrativas.']]:[])
]}
function visibleCertificates(){return adminView()&&isAdmin()?S.certificates:S.certificates.filter(c=>c.user===S.me.id)}
function managementOverview(){return '<section class="management-overview" aria-labelledby="management-title"><div class="section-head"><div><div class="eyebrow">ADMINISTRAÇÃO DA ACADEMIA</div><h2 id="management-title">O que você precisa gerenciar?</h2></div><span class="pill">'+roles[S.me.role]+'</span></div><div class="management-grid">'+managementItems().filter(([key])=>key!=='dashboard').map(([key,label,description])=>'<button type="button" class="management-card" data-go="'+key+'"><span class="management-icon">'+icon(key)+'</span><strong>'+label+'</strong><span>'+description+'</span><b aria-hidden="true">Acessar →</b></button>').join('')+'</div></section>'}
function nav(){const items=S.registrationPending?[]:adminView()?managementItems():[['dashboard','Meu aprendizado'],['courses','Meus cursos'],['forum','Fórum da comunidade'],['support','Pedir ajuda'],['certificates','Meus certificados'],['student-card','Minha carteirinha'],['notifications','Notificações'],['profile','Meu perfil']];$('#nav').innerHTML=items.map(([key,t])=>`<button data-go="${key}" class="${page===key?'active':''}"><span class="nav-icon">${icon(key)}</span>${t}</button>`).join('')+(!adminView()?`<a class="game-nav" href="https://operacao-fronteira-final.bbsone-2952.chatgpt.site" target="_blank" rel="noopener noreferrer" data-game-link><span class="nav-icon">${icon('game')}</span>Momento de distração<small>↗</small></a>`:'');$('#spaceLabel').textContent=S.registrationPending?(S.registrationPending.category==='company'?'CADASTRO DE EMPRESA · EM ANÁLISE':'MATRÍCULA · EM ANÁLISE'):adminView()?'GESTÃO DA ACADEMIA · '+roles[S.me.role].toUpperCase():'ÁREA DO ALUNO';$('#breadcrumb').textContent=(adminView()?'Empresa / ':'Aluno / ')+(items.find(i=>i[0]===page)?.[1]||'Sala de aula');$('#identity').innerHTML=avatar(S.me)+esc(S.me.name.split(' ')[0]);$('#switchSpace').hidden=!isStaff();$('#switchSpace').textContent=adminView()?'Área do aluno':'Painel da empresa';$('#noticeCount').textContent=S.notifications.filter(n=>!n.read).length;updateModerationBadge()}
async function refresh(){S=await api('bootstrap');S.notifications.forEach(n=>seenNotices.add(n.id));if(!isStaff())mode='student';nav()}
let navigationTrail=[],navigationCurrent=null;
function currentNavigationPlace(){return {page,courseId,lessonId,mode,forumTopic}}
async function portalGoBack(){const previous=navigationTrail.pop();if(previous){courseId=previous.courseId;lessonId=previous.lessonId;mode=isStaff()?previous.mode:'student';forumTopic=previous.forumTopic;return navigate(previous.page,true)}if(S&&page!=='dashboard')return navigate('dashboard',true);saveVideo();stopRecording();location.assign('/index.html')}
document.addEventListener('click',e=>{if(e.target.closest('[data-portal-back]')){e.preventDefault();void portalGoBack()}});
async function navigate(next,restoring=false){const target={...currentNavigationPlace(),page:next};if(!restoring&&navigationCurrent&&JSON.stringify(target)!==JSON.stringify(navigationCurrent)){navigationTrail.push({...navigationCurrent});if(navigationTrail.length>100)navigationTrail.shift()}stopRecording();saveVideo();page=next;navigationCurrent=currentNavigationPlace();nav();$('#view').classList.remove('page-enter');$('#view').innerHTML='<div class="loading"><div class="loader"></div></div>';try{await render();navigationCurrent=currentNavigationPlace();$('#view').classList.add('page-enter')}catch(e){$('#view').innerHTML=empty('Não foi possível carregar',esc(e.message),btn('Tentar novamente','retry'));toast(e.message,true)}}
async function render(){const view=$('#view');
 if(S.registrationPending){const company=S.registrationPending.category==='company';view.innerHTML=title('ANÁLISE DE CADASTRO','Solicitação recebida',company?'O cadastro da empresa aguarda análise da administração da academia.':'Um professor vai analisar sua solicitação de matrícula.')+`<section class="card"><div class="eyebrow">PRÓXIMO PASSO</div><h2>${company?'Aguardando a equipe administrativa':'Aguardando a equipe docente'}</h2><p>${company?'Após a análise, a equipe define quais opções de acesso serão liberadas para seu perfil.':'Após a aprovação do professor, o curso solicitado ficará disponível em Meu aprendizado.'}</p><p class="small">Enviaremos uma notificação quando houver uma atualização. Você pode sair e voltar mais tarde.</p><a class="btn secondary" href="/index.html">Voltar para a Home</a></section>`;return}
if(page==='dashboard'){
if(adminView()){const studentCount=S.people.filter(p=>p.role==='student').length;view.innerHTML=title('CENTRAL DE CONTROLE','Sua academia, em movimento.','Gerencie pessoas, organize conteúdos e acompanhe o aprendizado.',isAdmin()?btn('+ Cadastrar pessoa','new-person'):'')+`<section class="banner"><div><div class="eyebrow">ACADEMIA DO CAOS / GESTÃO</div><h2>Conhecimento bem organizado.<br>Aprendizado que avança.</h2><p>Comece pela grade do curso. Cadastre os alunos, libere as matrículas e acompanhe as dúvidas da comunidade.</p><div class="actions">${btn('Gerenciar cursos →','go-courses')}${!S.courses.some(c=>c.id==='cyber-pilot')&&isAdmin()?btn('Importar curso piloto','seed','','secondary'):''}</div></div><div class="banner-art">&lt;A/&gt;</div></section><div class="stat-grid"><div class="stat"><small>ALUNOS</small><b>${studentCount}</b><span>Cadastros na academia</span></div><div class="stat"><small>CURSOS</small><b>${S.courses.length}</b><span>${S.courses.filter(c=>c.published).length} publicados</span></div><div class="stat"><small>MATRÍCULAS</small><b>${S.enrollments.length}</b><span>Acessos liberados</span></div><div class="stat"><small>PROFESSORES</small><b>${S.people.filter(p=>p.active&&p.role==='teacher').length}</b><span>Disponíveis para suporte</span></div></div>${managementOverview()}<div class="two-col"><section class="card"><h2>Próximos passos</h2><p class="small">01 · Monte a grade, os vídeos e as avaliações.</p><p class="small">02 · Cadastre alunos e professores com o e-mail do login.</p><p class="small">03 · Matricule, publique e acompanhe a evolução.</p>${btn('Abrir catálogo','go-courses','','secondary')}</section><section class="card"><div class="eyebrow">CERTIFICAÇÃO</div><h2>Uma conquista por módulo.</h2><p class="small">Nome, RA, curso, carga horária e registro de verificação são preenchidos automaticamente.</p>${btn('Ver modelo profissional','sample-cert','','secondary')}</section></div>`;
}else{const recent=[...S.progress].sort((a,b)=>b.updated.localeCompare(a.updated))[0],continueCourse=S.courses.find(c=>c.id===recent?.course&&!courseLocked(c))||S.courses.find(c=>!courseLocked(c));view.innerHTML=title('SEU ESPAÇO DE EVOLUÇÃO',`Olá, ${esc(S.me.name.split(' ')[0])}.`,'Cada escolha consciente é um passo a mais na sua formação.')+`<section class="banner"><div><div class="eyebrow">SUA PRÓXIMA MISSÃO</div><h2>${continueCourse?esc(continueCourse.title):'Seu aprendizado começa aqui.'}</h2><p>${continueCourse?'Seu progresso está salvo. Volte para a última aula e continue no seu ritmo.':'Os cursos aparecem aqui assim que sua matrícula for liberada pela academia.'}</p>${continueCourse?btn('Continuar aprendizado →','open-course',continueCourse.id):''}</div><div class="banner-art">&lt;A/&gt;</div></section><div class="stat-grid"><div class="stat"><small>MEUS CURSOS</small><b>${S.courses.filter(c=>!c.development).length}</b><span>Trilhas liberadas</span></div><div class="stat"><small>AULAS CONCLUÍDAS</small><b>${S.progress.filter(p=>p.done).length}</b><span>Um passo de cada vez</span></div><div class="stat"><small>CERTIFICADOS</small><b>${visibleCertificates().length}</b><span>Conquistas registradas</span></div><div class="stat"><small>MEU RA</small><b style="font-size:17px;margin:10px 0">${esc(S.me.ra)}</b><span>Seu registro na academia</span></div></div>${learningMap()}<div class="section-head"><h2>Suas trilhas</h2><button class="text-button" data-go="courses">Ver todos →</button></div><div class="grid">${S.courses.slice(0,3).map(courseCard).join('')}</div>${!S.courses.length?empty('Sua próxima missão está chegando.','Aguarde a liberação de cursos pelo administrador.'):''}${renderEarnedBadges()}${S.courses.map(courseRecognition).join('')}`;}return}
if(page==='approvals'){if(!isStaff())throw Error('Acesso restrito à equipe da academia.');const requests=await api('registration-requests');view.innerHTML=title('CONTROLE DE ACESSO','Cadastros pendentes','Professores analisam solicitações de alunos. Cadastros de empresa ficam com os administradores.')+(!requests.length?empty('Tudo em dia.','Não há solicitações aguardando sua análise.'):`<div class="grid">${requests.map(r=>`<article class="card"><div class="eyebrow">${r.category==='company'?'CADASTRO DE EMPRESA':'MATRÍCULA DE ALUNO'}</div><h2>${esc(r.name)}</h2><p>${esc(r.email)} · RA ${esc(r.ra)}</p>${r.company?`<p>Empresa: ${esc(r.company)}</p>`:''}<p>Curso solicitado: ${esc(S.courses.find(c=>c.id===r.course)?.title||'Curso indisponível')}</p>${isAdmin()?`<label>Perfil após aprovação<select data-review-role="${esc(r.requestId)}"><option value="student">Aluno</option><option value="teacher">Professor</option><option value="admin">Administrador</option></select></label>`:''}<div class="actions">${btn('Aprovar','review-registration',r.requestId)}${btn('Recusar','reject-registration',r.requestId,'danger')}</div></article>`).join('')}</div>`);return}if(page==='student-card'){renderStudentCard();return}if(page==='reports'){await renderReports();return}if(page==='moderation'){await renderModeration();return}if(page==='courses'){view.innerHTML=title(adminView()?'CURADORIA DE CONTEÚDO':'BIBLIOTECA DE CURSOS',adminView()?'Cursos e grades':'Seu caminho de aprendizado',adminView()?'Organize pastas, níveis, módulos, vídeos e avaliações.':'Cursos organizados por pasta. Conclua cada etapa para liberar a próxima.',adminView()?btn('+ Novo curso','new-course'):'')+`<div class="toolbar"><input id="courseSearch" placeholder="Buscar curso..." aria-label="Buscar curso"><select id="folderFilter" aria-label="Pasta"><option value="">Todas as pastas</option>${[...new Set(S.courses.map(c=>c.folder))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="levelFilter" aria-label="Nível"><option value="">Todos os níveis</option><option>Básico</option><option>Intermediário</option><option>Difícil</option></select></div><div class="actions">${adminView()?catalogImports():''}${adminView()&&isAdmin()&&S.courses.some(c=>c.id==='cyber-pilot')?btn('Atualizar perguntas e portfólios da básica','sync-basic-content','','secondary'):''}</div><div class="grid" id="courseGrid">${S.courses.map(courseCard).join('')}</div>${!S.courses.length?empty('Seu catálogo está começando.',adminView()?'Crie o primeiro curso ou importe a trilha de conscientização já existente.':'Aguarde a liberação da sua matrícula.',adminView()&&isAdmin()?btn('Importar curso piloto','seed'):''):''}`;return}
if(page==='people'){if(!isAdmin())throw Error('Acesso administrativo necessário.');view.innerHTML=title('PESSOAS E PERMISSÕES','Alunos e equipe','Nome, RA, contato, perfil e acesso em um só lugar.',btn('+ Cadastrar pessoa','new-person'))+`<div class="toolbar"><input id="peopleSearch" aria-label="Buscar pessoa" placeholder="Buscar nome, RA ou e-mail..."></div><div class="table-wrap"><table><thead><tr><th>PESSOA</th><th>RA</th><th>PERFIL</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody id="peopleRows">${S.people.map(personRow).join('')}</tbody></table></div><div class="notice">O participante entra com o e-mail ou RA e a senha pessoal cadastrada. Senhas não são exibidas no painel.</div>`;return}
if(page==='enrollments'){view.innerHTML=title('LIBERAÇÃO DE ACESSOS','Matrículas','Defina os cursos disponíveis para cada aluno.')+`<section class="card"><h2>Nova matrícula</h2><form id="enrollForm"><div class="form-grid"><label>Aluno<select name="user" required>${S.people.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.ra)}</option>`).join('')}</select></label><label>Curso<select name="course" required>${S.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label></div><button class="btn" ${!S.people.length||!S.courses.length?'disabled':''}>Liberar matrícula →</button></form></section><div class="table-wrap"><table><thead><tr><th>ALUNO</th><th>CURSO</th><th>PROGRESSO</th><th>AÇÃO</th></tr></thead><tbody>${S.enrollments.map(e=>{const user=S.people.find(p=>p.id===e.user),c=S.courses.find(c=>c.id===e.course),count=(S.allProgress||[]).filter(p=>p.user===e.user&&p.course===e.course&&p.done).length;return `<tr><td>${esc(user?.name)}</td><td>${esc(c?.title)}</td><td>${count} de ${c?lessons(c).length:0} aulas</td><td>${btn('Revogar acesso','remove-enrollment',e.user+'|'+e.course,'danger')}</td></tr>`}).join('')}</tbody></table></div>`;return}
if(page==='classroom'){renderClassroom();return}
if(page==='profile'){const mfa=await api('auth/totp-status');view.innerHTML=title('SUA IDENTIDADE NA ACADEMIA','Meu perfil','Mantenha seu cadastro e sua foto atualizados.')+`<div class="two-col"><section class="card"><div class="profile-hero">${avatar(S.me,true)}<div><h2>${esc(S.me.name)}</h2><span class="pill">${esc(S.me.ra)}</span> <span class="pill grey">${roles[S.me.role]}</span></div></div><form id="profileForm"><label>Nome completo<input name="name" required maxlength="120" value="${esc(S.me.name)}"></label><label>E-mail de contato<input name="email" type="email" required value="${esc(S.me.email)}"></label><label>Foto de perfil · JPG, PNG ou WebP<input id="profilePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="btn">Salvar meu perfil →</button></form></section><section class="card"><div class="eyebrow">ACESSO E SEGURANÇA</div><h2>Sua conta protegida.</h2><p class="small">E-mail de acesso: <strong>${esc(S.me.login_email)}</strong></p><p class="small">Entre com seu e-mail ou RA e a senha da academia. <a href="login.html?mode=password">Alterar senha</a> · <a href="login.html?mode=recover">Recuperar acesso</a>.</p><p class="small">O RA é único e permanece associado ao seu histórico de aprendizagem e aos certificados.</p><hr><div class="eyebrow">AUTENTICAÇÃO EM DUAS ETAPAS</div><h3>${mfa.enabled?'Proteção ativada':'Adicione uma camada extra de proteção'}</h3><p class="small">${mfa.enabled?'No próximo login, além da senha, informe um código temporário do aplicativo autenticador.':'Use Aegis, Google Authenticator ou Microsoft Authenticator. O aplicativo gera um novo código de seis dígitos a cada 30 segundos.'}</p>${!mfa.configured?'<p class="notice warn">A equipe ainda precisa configurar a chave de criptografia do autenticador no servidor.</p>':mfa.enabled?btn('Desativar autenticação em duas etapas','disable-totp','','secondary'):btn('Configurar aplicativo autenticador','setup-totp')}<p class="small muted">Guarde o celular com segurança. Se perder acesso ao autenticador, a equipe precisará ajudar na recuperação da conta.</p><a class="btn secondary" href="login.html" data-auth-logout>Sair e trocar conta</a></section></div>`;return}
if(page==='forum'){await renderForum();return}
if(page==='support'){await renderSupport();return}
if(page==='notifications'){view.innerHTML=title('ACOMPANHE AS NOVIDADES','Notificações','Atualizações dos cursos, matrículas, respostas e mensagens no fórum.',btn('Marcar todas como lidas','read-notices','','secondary')+soundControls())+(adminView()?`<section class="card"><h2>Publicar atualização</h2><form id="announcementForm"><div class="form-grid"><label>Curso<select name="course">${S.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label><label>Título<input name="title" required maxlength="180"></label></div><label>Mensagem<textarea name="text" required rows="3" maxlength="2000"></textarea></label><button class="btn">Notificar alunos →</button></form></section>`:'')+`<section class="card" style="padding:0">${S.notifications.length?S.notifications.map(n=>`<article class="notification ${n.read?'':'unread'}"><span class="avatar">${n.read?'✓':'●'}</span><div><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p><small>${dateTime(n.created)}</small>${n.course?`<button class="text-button" data-action="${n.title==='Nova mensagem no fórum'?'notice-forum':'notice-course'}" data-id="${esc(n.course)}">${n.title==='Nova mensagem no fórum'?'Ver conversa':'Abrir curso'} →</button>`:''}</div></article>`).join(''):empty('Tudo em dia.','As novidades da academia aparecem aqui.')}</section>`;return}
if(page==='certificates'){view.innerHTML=title('APRENDIZADO QUE MERECE REGISTRO',adminView()?'Certificação da academia':'Minhas conquistas','Certificados por módulo e por curso, com dados preenchidos automaticamente.',btn('Conhecer o modelo','sample-cert','','secondary'))+`<div class="grid">${visibleCertificates().map(cert=>{const s=JSON.parse(cert.snapshot);return `<article class="certificate-card"><span class="award">${icon("certificates")}</span><div class="eyebrow">${esc(s.module)}</div><h3>${esc(s.course)}</h3><p>${esc(s.name)}</p><small>${s.hours} h · ${date(cert.created)} · ${esc(s.code)}</small>${btn('Abrir certificado →','view-cert',cert.id,'secondary')}</article>`}).join('')}</div>${!adminView()?S.courses.map(courseRecognition).join('')+S.courses.map(c=>'<div class="lesson-awards">'+lessons(c).map(l=>lessonRecognition(c,l)).join('')+'</div>').join(''):''}${!visibleCertificates().length?empty(adminView()?'Nenhum certificado emitido.':'Sua próxima conquista está à frente.',adminView()?'Os certificados aparecerão após a conclusão e a emissão pelos participantes.':'Conclua as aulas e avaliações de um módulo para liberar o certificado.'):''}`;return}
if(page==='settings'){view.innerHTML=title('AJUSTES DA ACADEMIA','Configurações','Controle dos recursos de atendimento e acesso.')+`<section class="card"><h2>Cópia de segurança do banco</h2><p>Exporte os cadastros, cursos e históricos completos para uma migração. O arquivo é confidencial e deve ser guardado em local seguro. Sessões de acesso e senhas temporárias não são incluídas.</p><a class="btn secondary" href="/api/lms/database-export" download>Exportar banco (JSON) ↓</a></section><section class="card"><div class="status-line"><h2>Assistente de estudo</h2><span class="pill ${S.aiAvailable?'':'orange'}">${S.robot?(S.aiAvailable?'IA conectada':'Consulta aos materiais · sem IA'):'Desativado'}</span></div><p>O assistente consulta aulas e materiais já liberados, incluindo transcrições das legendas WebVTT dos vídeos. Dúvidas sem resposta segura podem ser encaminhadas a um professor. Sem integração externa, exibe trechos do material e informa que não usa IA.</p><div class="notice ${S.aiAvailable?'':'warn'}">${S.aiAvailable?'A integração de IA está configurada. As respostas serão identificadas como automáticas.':'Modo disponível: consulta automática aos materiais, sem IA e sem serviços externos. O atendimento com professores permanece disponível.'}</div>${btn(S.robot?'Desativar assistente':'Ativar consulta aos materiais','toggle-robot','','secondary')}</section><section class="card"><h2>Login e permissões</h2><p class="small">Entre com o e-mail ou RA cadastrado e a senha pessoal da academia. O primeiro acesso e a recuperação usam o e-mail confirmado no cadastro. Professores podem editar cursos e responder ao suporte. Administradores também gerenciam pessoas, matrículas e configurações.</p></section>`;return}
if(page==='audit'){const rows=await api('audit');view.innerHTML=title('RASTREABILIDADE','Histórico de ações','Últimas alterações administrativas registradas no servidor.')+`<div class="table-wrap"><table><thead><tr><th>DATA</th><th>RESPONSÁVEL</th><th>AÇÃO</th><th>REFERÊNCIA</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateTime(r.created)}</td><td>${esc(r.name)}</td><td>${esc(r.action)}</td><td class="audit">${esc(r.target)}</td></tr>`).join('')}</tbody></table></div>`;return}}
