function openDialog(html,wide=false){const d=$('#editorDialog');d.classList.toggle('wide',wide);$('#dialogBody').innerHTML=html;if(!d.open)d.showModal();d.scrollTop=0;$('#dialogBody').scrollTop=0}
function closeDialog(){assessmentAdvance=null;if(editor&&$('#courseForm')&&!confirm('Fechar o editor? Alterações não salvas serão descartadas.'))return;editor=null,documentUrls=[],recordBusy=false,audioPreviewUrl='',soundContext=null,soundEnabled=localStorage.getItem('academy-notification-sound')!=='off',seenNotices=new Set(),pollBusy=false,forumTopic='',forumTopics=[],reportRows=[],lastTutor=null;$('#editorDialog').close()}
function personEditor(pid){const p=S.people.find(p=>p.id===pid)||{name:'',email:'',login_email:'',role:'student',active:1};openDialog(`<h2 class="dialog-title">${pid?'Gerenciar cadastro':'Cadastrar pessoa'}</h2><form id="personForm" data-id="${esc(pid)}"><label>Nome completo<input name="name" required maxlength="120" value="${esc(p.name)}"></label><div class="form-grid"><label>E-mail de acesso<input name="login_email" type="email" required value="${esc(p.login_email)}" ${p.identity?'readonly':''}></label><label>E-mail de contato<input name="email" type="email" required value="${esc(p.email)}"></label><label>Perfil<select name="role">${Object.entries(roles).map(([v,t])=>`<option value="${v}" ${p.role===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Situação<select name="active"><option value="1" ${p.active?'selected':''}>Ativo</option><option value="0" ${!p.active?'selected':''}>Inativo</option></select></label></div>${pid?`<p class="small muted">RA: <strong>${esc(p.ra)}</strong> · Criado em ${date(p.created)}</p>`:'<p class="small muted">Um RA único será gerado automaticamente. Novos alunos recebem matrícula na trilha básica publicada. Gerencie os demais acessos na página Matrículas.</p>'}<div class="notice">O participante define ou recupera a senha da academia em Primeiro acesso / Esqueci minha senha, usando o e-mail ou RA cadastrado. A administração deve conferir o e-mail do cadastro antes de orientar a recuperação.</div><button class="btn">${pid?'Salvar alterações':'Cadastrar pessoa'} →</button></form>`)}
function newCourse(){return {title:'',description:'',folder:'Cyber',level:'Básico',sort:0,published:0,modules:[]}}
function courseEditor(cid){editor=structuredClone(S.courses.find(c=>c.id===cid)||newCourse());drawEditor()}
function moduleEditor(m,mi){return `<section class="editing-module" data-module="${mi}"><div class="lesson-edit-head"><strong>MÓDULO ${mi+1}</strong><div>${mi?btn('↑','module-up',mi,'secondary'):''} ${btn('Remover módulo','remove-module',mi,'danger')}</div></div><div class="form-grid"><label>Nome do módulo<input data-field="module-title" data-m="${mi}" required maxlength="180" value="${esc(m.title)}"></label><label>Carga horária para certificado (horas)<input type="number" min="0.01" max="500" step="0.01" data-field="module-hours" data-m="${mi}" required value="${m.hours}"></label></div>${m.lessons.map((l,li)=>lessonEditor(l,mi,li)).join('')}${btn('+ Adicionar aula','add-lesson',mi,'secondary')}</section>`}
function lessonEditor(l,mi,li){const data=`data-m="${mi}" data-l="${li}"`;return `<section class="editing-lesson"><div class="lesson-edit-head"><strong>AULA ${li+1}</strong><div>${li?btn('↑','lesson-up',mi+'|'+li,'secondary'):''} ${btn('Remover','remove-lesson',mi+'|'+li,'danger')}</div></div><label>Título<input data-field="lesson-title" ${data} required maxlength="180" value="${esc(l.title)}"></label><label>Descrição e material de apoio<textarea data-field="lesson-description" ${data} rows="5" maxlength="12000">${esc(l.description)}</textarea></label><label>Cenário<textarea data-field="lesson-scenario" ${data} maxlength="4000">${esc(l.scenario||'')}</textarea></label><label>Decisão prática<textarea data-field="decision-prompt" ${data} maxlength="1000">${esc(l.decision?.prompt||'')}</textarea></label><label>Orientação<textarea data-field="decision-orientation" ${data} maxlength="4000">${esc(l.decision?.orientation||'')}</textarea></label><div class="form-grid"><label>Tempo estimado (minutos)<input type="number" min="1" max="300" data-field="lesson-minutes" ${data} value="${l.minutes}"></label><label>Vídeo · MP4 ou WebM · até 90 MB<input type="file" accept="video/mp4,video/webm,video/ogg" data-upload="video" ${data} ${!editor.id?'disabled':''}></label></div>${l.video?`<p class="small">✓ Vídeo vinculado ${btn('Remover vídeo','clear-video',mi+'|'+li,'secondary')}</p>`:`<p class="small muted">${editor.id?'Sem vídeo. A aula funciona como leitura até o envio do arquivo.':'Salve o rascunho para habilitar o upload de vídeos.'}</p>`}<div class="media-editor"><h3>Vídeo, legendas e tutor</h3><p class="small muted">O tutor usa automaticamente a transcrição das legendas para responder sobre esta aula. Envie um arquivo WebVTT (.vtt) em português ou no idioma do vídeo. Sem legenda, o tutor usa apenas a descrição e os materiais da aula.</p><div class="form-grid"><label>Qualidade da versão<select id="quality-${mi}-${li}"><option>480p</option><option>720p</option><option>1080p</option></select><input type="file" aria-label="Enviar versão de vídeo" accept="video/mp4,video/webm" data-upload="quality" ${data} ${!editor.id?'disabled':''}></label><label>Idioma da legenda<select id="caption-${mi}-${li}"><option value="pt">Português</option><option value="en">English</option><option value="es">Español</option></select><input type="file" aria-label="Enviar legenda WebVTT" accept=".vtt,text/vtt" data-upload="caption" ${data} ${!editor.id?'disabled':''}></label></div><div class="media-list">${(l.sources||[]).map((v,vi)=>`<div><span>Vídeo ${esc(v.label)}</span>${btn('Remover versão','remove-source',mi+'|'+li+'|'+vi,'secondary')}</div>`).join('')}${(l.captions||[]).map((v,vi)=>`<div><span>Legenda: ${esc(v.label)}</span>${btn('Remover legenda','remove-caption',mi+'|'+li+'|'+vi,'secondary')}</div>`).join('')}${(l.video&&!(l.captions||[]).length)?'<p class="small warn">Este vídeo ainda não tem transcrição disponível ao tutor.</p>':''}</div></div><div class="section-head"><h3>Avaliação da aula</h3>${btn('+ Pergunta','add-question',mi+'|'+li,'secondary')}</div>${l.quiz.map((q,qi)=>`<div class="editing-question"><div class="lesson-edit-head"><strong>PERGUNTA ${qi+1}</strong>${btn('Remover','remove-question',mi+'|'+li+'|'+qi,'danger')}</div><label>Enunciado<textarea data-field="question" ${data} data-q="${qi}" required rows="2">${esc(q.question)}</textarea></label><div class="options">${q.options.map((o,oi)=>`<label>Alternativa ${oi+1}<input data-field="option" ${data} data-q="${qi}" data-o="${oi}" required value="${esc(o)}"></label>`).join('')}</div><label>Explicação da resposta<textarea data-field="explanation" ${data} data-q="${qi}" maxlength="1800">${esc(q.explanation||'')}</textarea></label><label>Resposta correta<select data-field="answer" ${data} data-q="${qi}">${q.options.map((o,oi)=>`<option value="${oi}" ${oi===q.answer?'selected':''}>Alternativa ${oi+1}</option>`).join('')}</select></label></div>`).join('')}</section>`}
function drawEditor(){const c=editor;openDialog(`<h2 class="dialog-title">${c.id?'Editar curso e grade':'Criar curso'}</h2><p class="small muted">A ordem dos módulos e das aulas define a liberação sequencial. Avaliações exigem 75% de aproveitamento.</p><form id="courseForm"><div class="form-grid"><label class="full">Nome do curso<input name="title" data-course="title" required maxlength="180" value="${esc(c.title)}"></label><label>Pasta do curso<input name="folder" data-course="folder" required maxlength="100" value="${esc(c.folder)}"></label><label>Nível<select name="level" data-course="level">${['Básico','Intermediário','Difícil'].map(v=>`<option ${c.level===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Ordem na pasta<input type="number" min="0" name="sort" data-course="sort" value="${c.sort}"></label><label>Visibilidade<select name="published" data-course="published"><option value="0" ${!c.published?'selected':''}>Rascunho</option><option value="1" ${c.published?'selected':''}>Publicado</option></select></label><label class="full">Descrição do curso<textarea name="description" data-course="description" rows="3" maxlength="4000">${esc(c.description)}</textarea></label></div><div class="section-head"><h2>Grade curricular</h2>${btn('+ Módulo','add-module','','secondary')}</div>${c.modules.map(moduleEditor).join('')}${!c.modules.length?empty('Monte o primeiro módulo.','Defina o nome, a carga horária e as aulas.'):''}<div class="sticky-save"><button type="submit" class="btn">Salvar curso e grade →</button>${c.id?btn('Abrir sala','preview-course',c.id,'secondary'):''}${c.id&&isAdmin()?btn('Arquivar','archive-course',c.id,'danger'):''}<span id="editorStatus" class="small muted"></span></div></form>`,true)}
let quizSubmitting=false;
async function submitLessonQuiz(form){if(quizSubmitting)return;const fields=[...form.querySelectorAll('fieldset')];if(!fields.length||fields.some(field=>!field.querySelector('input[type=radio]:checked')))return;const video=$('#lessonVideo');if(video&&!videoEnded){$('#lessonResult').textContent='Resposta marcada. Ao terminar o vídeo, a avaliação será corrigida automaticamente.';return}quizSubmitting=true;const submit=form.querySelector('#completeLesson');if(submit)submit.disabled=true;try{const c=S.courses.find(c=>c.id===courseId),l=lessons(c).find(l=>l.id===lessonId),answers=l.quiz.map((_,i)=>Number(new FormData(form).get('q'+i))),result=await completeLesson(answers);if(result?.passed===false){fields.forEach(field=>field.querySelectorAll('input').forEach(input=>input.disabled=false));fields.forEach(field=>field.querySelector('.quiz-option.incorrect')?.classList.remove('incorrect'));(result.incorrect||[]).forEach(i=>fields[i]?.querySelector('input[type=radio]:checked')?.closest('.quiz-option')?.classList.add('incorrect'));if(submit)submit.disabled=false}}catch(error){if(submit)submit.disabled=false;$('#lessonResult').textContent=error.message}finally{quizSubmitting=false}}
async function loadLessonReview(course,lesson){const target=$('#lessonReview');try{const review=await api('lesson-review?'+new URLSearchParams({course,lesson}));if($('#lessonReview')!==target)return;target.innerHTML='<h3>Revisão da avaliação</h3><p>Sua nota registrada: '+esc(review.score??'—')+'%. Esta revisão não altera seu resultado.</p>'+review.questions.map((q,i)=>'<section class="notice"><strong>'+esc((i+1)+'. '+q.question)+'</strong><p>Resposta correta: '+esc(q.options[q.answer])+'</p><p>'+esc(q.explanation)+'</p></section>').join('')}catch(e){if($('#lessonReview')===target)target.textContent=e.message}}
function renderClassroom(){const c=S.courses.find(c=>c.id===courseId);if(!c)throw Error('Curso indisponível.');if(courseLocked(c))throw Error(c.development?'Esta trilha está em desenvolvimento.':'Conclua o curso anterior desta pasta.');const ls=lessons(c);if(!ls.length){$('#view').innerHTML=title('SALA DE AULA',esc(c.title))+empty('Grade em preparação.','O professor ainda está preparando as aulas deste curso.');return}let l=ls.find(x=>x.id===lessonId);if(!l||!allowed(c,l)){const last=S.progress.filter(p=>p.course===c.id).sort((a,b)=>b.updated.localeCompare(a.updated))[0];l=ls.find(x=>x.id===last?.lesson&&!progress(c.id,x.id)?.done)||ls.find(x=>!progress(c.id,x.id)?.done&&allowed(c,x))||ls[0];lessonId=l.id}videoEnded=!!progress(c.id,l.id)?.done;videoSave=0;const videoSrc=l.video?asset(l.video):(c.id==='cyber-pilot'?(l.module==='pilot-m1'&&l.id==='pilot-l1'?'/assets/videos/modulo-01-aula-01.mp4':l.module==='pilot-m2'&&l.id==='pilot-l2'?'/assets/videos/modulo-02-aula-01.mp4':l.module==='pilot-m3'&&l.id==='pilot-l3'?'/assets/videos/modulo-03-aula-01.mp4':''):'');const reviewing=!!progress(c.id,l.id)?.done,m=c.modules.find(m=>m.id===l.module);$('#view').innerHTML=title(`${esc(c.folder)} / ${esc(c.level)}`,esc(c.title),`${esc(m.title)} · ${completed(c)} de ${ls.length} aulas concluídas`,btn('← Meus cursos','go-courses','','secondary'))+`<div class="course-layout"><section>${l.scenario?`<article class="card"><div class="eyebrow">CENÁRIO / CONTEXTO DA EMPRESA</div><h2>${esc(l.title)}</h2><p class="lesson-description">${esc(l.scenario)}</p></article>`:''}<div class="${videoSrc?'':'reading-cover'}">${videoSrc?`<video id="lessonVideo" class="lesson-player" controls preload="metadata" playsinline data-course="${esc(c.id)}" data-lesson="${esc(l.id)}" src="${esc(videoSrc)}">${(l.captions||[]).map((cap,i)=>`<track kind="subtitles" label="${esc(cap.label)}" srclang="${esc(cap.lang)}" src="${asset(cap.asset)}" ${i===0?'default':''}>`).join('')}</video>`:`<div class="eyebrow">${l.plannedVideoMinutes?'VÍDEO EM PREPARAÇÃO / APROX. 5 MIN':'AULA DE LEITURA / '+l.minutes+' MIN'}</div><h2>${esc(l.title)}</h2><p>Leia o material abaixo e responda à avaliação para concluir esta etapa.</p>`}</div>${videoSrc?`<div class="player-tools"><label>Velocidade<select id="playbackSpeed">${[.5,.75,1,1.25,1.5,1.75,2].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}×</option>`).join('')}</select></label><label>Qualidade<select id="qualitySelect"><option value="${esc(videoSrc)}">Original</option>${(l.sources||[]).map(v=>`<option value="${esc(v.asset)}">${esc(v.label)}</option>`).join('')}</select></label><span class="small muted">${((l.captions||[]).length)?'Legendas disponíveis no botão CC do player.':'Legendas ainda não disponibilizadas pelo professor.'}</span></div>`:''}<div class="card" style="margin-top:20px"><div class="status-line"><span class="pill">${esc(c.level)}</span><span class="small muted">${l.minutes} min · ${m.hours} h no módulo</span></div><h2>${esc(l.title)}</h2><p class="lesson-description">${esc(l.description)}</p>${(l.materials||[]).map(r=>`<a class="lesson-material" href="${esc(r.url)}" target="_blank" rel="noopener">📘 ${esc(r.title)} <span aria-hidden="true">↗</span></a>`).join('')}${reviewing?'<div class="notice lesson-review-notice"><strong>Modo de revisão · Aula concluída</strong><p>Reveja o vídeo e o portfólio no seu ritmo. Sua nota, seu selo e sua conclusão permanecem salvos.</p></div>':'<label><input id="autoplayNext" type="checkbox" checked>Avançar automaticamente ao concluir a aula</label>'}<div class="notice">${reviewing?'Esta aula já foi concluída. Você pode rever o conteúdo sem refazer a avaliação.':videoSrc?'Ao terminar o vídeo, a próxima aula é liberada. Se houver avaliação, responda primeiro às perguntas abaixo.':'Conclua a leitura e a avaliação para liberar a próxima aula.'}${!reviewing&&l.quiz.length?' Responda às '+l.quiz.length+' perguntas. Mínimo de '+Math.ceil(l.quiz.length*.75)+' acertos.':''}</div>${l.decision?`<section class="notice"><div class="eyebrow">DECISÃO PRÁTICA</div><h3>${esc(l.decision.prompt)}</h3><p>Defina seu próximo passo antes de consultar a orientação.</p><details><summary>Comparar com a orientação</summary><p>${esc(l.decision.orientation)}</p></details></section>`:''}${reviewing?'<div id="lessonReview" aria-live="polite">Carregando a revisão comentada...</div>':`<form id="lessonQuiz">${(l.quiz||[]).map((q,qi)=>`<fieldset class="quiz-question"><legend>PERGUNTA ${qi+1}</legend><strong>${esc(q.question)}</strong>${q.options.map((o,oi)=>`<label class="quiz-option"><input type="radio" name="q${qi}" value="${oi}" required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}<div id="lessonFeedback" aria-live="polite"></div><p id="lessonResult" role="status" class="inline-alert"></p><button class="btn" ${videoSrc&&!videoEnded?'disabled':''} id="completeLesson">${progress(c.id,l.id)?.done?'Aula concluída · Continuar →':l.quiz.length?'Enviar avaliação e concluir →':'Concluir aula →'}</button></form>`}</div>${lessonRecognition(c,l)}${moduleBadges.card(moduleAchievement(c,m))}${courseRecognition(c)}</section><aside class="curriculum"><div class="card"><h3>Seu percurso</h3><div class="course-meta"><span>${pct(c)}% concluído</span><span>${hours(c)} h</span></div><div class="progress-track"><span style="width:${pct(c)}%"></span></div>${c.modules.map((mod,i)=>`<details class="module" ${mod.id===l.module?'open':''}><summary>${i+1}. ${esc(mod.title)}<small>${mod.hours} h · ${mod.lessons.length} aulas</small></summary>${mod.lessons.map(x=>`<button class="lesson-link ${x.id===l.id?'active':''}" data-action="open-lesson" data-id="${esc(x.id)}" ${allowed(c,x)?'':'disabled'}>${progress(c.id,x.id)?.done?'✓':allowed(c,x)?'▷':'🔒'}<span>${progress(c.id,x.id)?.done?'<small class="lesson-review-label">Rever aula · Concluída</small>':''}${esc(x.title)}</span></button>`).join('')}${moduleAchievement(c,mod)?`<span class="ac-badge-curriculum">✓ Selo ${esc(moduleAchievement(c,mod).name)}</span>`:''}${c.certification?.modules.find(x=>x.id===mod.id)?.eligible?`<div style="padding:10px">${btn('Emitir certificado','issue-cert',c.id+'|'+mod.id,'secondary')}</div>`:''}</details>`).join('')}${c.certification?.passed?btn('Certificado do curso','issue-cert',c.id+'|course'):c.certification?.ready?btn('Avaliação de fechamento','course-assessment',c.id,'secondary'):''}<button class="link-block text-button" data-go="support">Preciso de ajuda →</button></div></aside></div>`;if(reviewing)void loadLessonReview(c.id,l.id);const v=$('#lessonVideo');if(v){let rate=1;try{rate=Number(localStorage.getItem('caos-playback-speed'))||1}catch{}v.playbackRate=[.5,.75,1,1.25,1.5,1.75,2].includes(rate)?rate:1;$('#playbackSpeed').value=String(v.playbackRate);v.addEventListener('loadedmetadata',()=>{const at=reviewing?0:progress(c.id,l.id)?.position||0;if(at<v.duration-3)v.currentTime=at});v.addEventListener('timeupdate',()=>{if(Date.now()-videoSave>10000){videoSave=Date.now();saveVideo()}});v.addEventListener('pause',saveVideo);v.addEventListener('ended',async()=>{if(reviewing)return;videoEnded=true;$('#completeLesson').disabled=false;if(!l.quiz.length)try{await completeLesson([])}catch(e){toast(e.message,true)}else{$('#lessonResult').textContent='Vídeo concluído. Responda à avaliação para avançar.';$('#lessonQuiz').scrollIntoView({behavior:'smooth',block:'nearest'});submitLessonQuiz($('#lessonQuiz'))}})}}
function saveVideo(){const v=$('#lessonVideo');if(!v||!v.dataset.course||!v.dataset.lesson||!S)return;const pc=v.dataset.course,pl=v.dataset.lesson;let saved=S.progress.find(p=>p.course===pc&&p.lesson===pl);if(saved?.done)return;if(!saved){saved={course:pc,lesson:pl,done:0};S.progress.push(saved)}saved.position=Math.floor(v.currentTime);saved.updated=new Date().toISOString();const body=JSON.stringify({course:pc,lesson:pl,position:v.currentTime});fetch('/api/lms/progress',{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true}).catch(()=>{})}
async function completeLesson(answers){
 if(completingLesson)return;
 completingLesson=true;
 try{
  const auto=$('#autoplayNext')?.checked,c=S.courses.find(x=>x.id===courseId),ls=lessons(c),at=ls.findIndex(l=>l.id===lessonId),v=$('#lessonVideo'),submittedLesson=lessonId;
  const currentModule=c.modules.find(m=>m.lessons.some(l=>l.id===submittedLesson)),wasComplete=moduleComplete(c,currentModule);
  const result=await api('progress','POST',{course:c.id,lesson:submittedLesson,complete:true,answers,videoEnded,position:v?.currentTime||0});
  if(!result.passed){if(result.feedback)$('#lessonFeedback').innerHTML=assessmentFeedback(result.feedback);$('#lessonResult').textContent=`Resultado: ${result.score}%. É necessário acertar 75%. Revise as alternativas e tente novamente.`;return result}
  await refresh();
  if(courseId!==c.id||lessonId!==submittedLesson)return;
  toast('Aula concluída. Progresso salvo!');
  const freshCourse=S.courses.find(x=>x.id===c.id),freshModule=freshCourse?.modules.find(m=>m.id===currentModule.id);
  const achievement=freshModule&&!wasComplete?moduleAchievement(freshCourse,freshModule):undefined;
  const advance=()=>{
   if(auto&&ls[at+1]){lessonId=ls[at+1].id;renderClassroom();const nextVideo=$('#lessonVideo');if(nextVideo)nextVideo.play().catch(()=>toast('Próxima aula pronta. Toque em reproduzir para continuar.'))}
   else{renderClassroom();if(at===ls.length-1)toast(freshCourse.certification?.passed?'Formação concluída! Seu certificado final está liberado.':'Módulos concluídos! Faça a avaliação final para liberar o certificado do curso.')}
   $('#view').focus();
  };
  const review=()=>{
   if(result.feedback){renderClassroom();assessmentAdvance=advance;openDialog('<h2>Avaliação concluída · '+result.score+'%</h2>'+lessonRecognition(freshCourse,ls[at])+assessmentFeedback(result.feedback)+btn('Continuar aprendizado →','assessment-continue'))}
   else advance();
  };
  if(achievement){
   renderClassroom();
   moduleBadges.celebrate(achievement,{continueLabel:result.feedback?'Ver correção da avaliação':auto&&ls[at+1]?'Continuar para a próxima aula':'Continuar aprendizado',onContinue:review,onDismiss:()=>$('#completeLesson')?.focus()});
  }else review();
  return result;
 }finally{completingLesson=false}
}
