if(f.id==='messageForm'){if(recording?.state==='recording')throw Error('Pare a gravação antes de enviar.');const file=$('#forumFile').files[0]||pendingAudio;const fileId=file?await upload(file,'forum',courseId):'';await api('forum?course='+encodeURIComponent(courseId),'POST',{text:data.text,asset:fileId,parent:forumParent,topic:forumTopic});f.reset();pendingAudio=null;forumParent='';$('#replyTo').textContent='';$('#fileStatus').textContent='Mensagem enviada.';return loadMessages()}
