async function start(){try{await refresh();if(requestedAdmin&&!isStaff()&&!S.registrationPending){const error=new Error('Seu perfil não tem permissão para o painel da empresa. Acesse a área do aluno ou solicite acesso ao administrador.');error.status=403;throw error;}if(isAdmin()&&!S.courses.length){await api('seed','POST',{});await refresh()}const forum=new URLSearchParams(location.search).get('forum');if(forum&&S.courses.some(c=>c.id===forum&&!courseLocked(c))){courseId=forum;await navigate('forum')}else await navigate('dashboard');const check=new URLSearchParams(location.search).get('certificate');if(check)await showCert(check)}catch(e){$('#view').innerHTML=empty(e.status===401?'Entre na sua academia.':e.status===403?'Acesso restrito.':'Não foi possível carregar a academia.',esc(e.message),'<a class="btn" href="login.html">Entrar na academia →</a><a class="link-block" href="/aluno.html">Acessar área do aluno</a><a class="link-block" href="index.html">Voltar para a Home</a>');$('#nav').innerHTML='';$('#identity').textContent='Acesso protegido'}}
async function pollActivity(){if(!S||pollBusy||$('#editorDialog').open)return;pollBusy=true;try{const next=await api('bootstrap');const fresh=next.notifications.filter(n=>!n.read&&!seenNotices.has(n.id));next.notifications.forEach(n=>seenNotices.add(n.id));S.notifications=next.notifications;if(fresh.length){playNoticeSound();toast(fresh.length===1?fresh[0].title:`${fresh.length} novas notificações na academia.`)}$('#noticeCount').textContent=S.notifications.filter(n=>!n.read).length;if(!document.hidden&&page==='forum'&&courseId)await loadMessages()}catch{}finally{pollBusy=false}}
setInterval(pollActivity,8000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)void pollActivity()});
function updateModerationBadge(){const button=document.querySelector('[data-go=moderation]');if(!button)return;button.querySelector('.moderation-count')?.remove();if(S.moderationPending){const badge=document.createElement('small');badge.className='moderation-count';badge.textContent=S.moderationPending;badge.setAttribute('aria-label',S.moderationPending+' denúncias pendentes');button.append(badge)}}

